const items = $input.all();
const crypto = require('crypto');
const results = [];
for (const item of items) {
  const content = JSON.stringify(item.json.body || item.json);
  const hash = crypto.createHash('sha256').update(content).digest('hex').substring(0, 12);
  const version = `v${new Date().toISOString().split('T')[0].replace(/-/g, '')}-${hash}`;
  results.push({
    json: {
      version,
      hash,
      documentName: item.json.body?.documentName || 'untitled',
      author: item.json.body?.author || 'system',
      timestamp: new Date().toISOString(),
      changeDescription: item.json.body?.changeDescription || 'No description',
      contentSize: content.length
    }
  });
}
return results;

